package com.securelock.app;
import android.content.Context;import android.content.SharedPreferences;import java.security.MessageDigest;import java.security.SecureRandom;
public final class SecureLockPrefs {
 private static final String P="secure_lock"; private SecureLockPrefs(){} private static SharedPreferences p(Context c){return c.getSharedPreferences(P,Context.MODE_PRIVATE);}
 public static boolean hasPin(Context c){return p(c).contains("hash")&&p(c).contains("salt");} public static boolean isEnabled(Context c){return p(c).getBoolean("enabled",false);} public static boolean screenLockEnabled(Context c){return p(c).getBoolean("screenlock",true);} public static boolean lockScreenEnabled(Context c){return screenLockEnabled(c);} public static void setScreenLockEnabled(Context c,boolean v){p(c).edit().putBoolean("screenlock",v).apply();}
 public static void savePin(Context c,String pin)throws Exception{byte[] salt=new byte[16];new SecureRandom().nextBytes(salt);p(c).edit().putString("salt",hex(salt)).putString("hash",hex(hash(pin,salt))).putBoolean("enabled",true).apply();}
 public static boolean verifyPin(Context c,String pin){try{String s=p(c).getString("salt","");String h=p(c).getString("hash","");return !s.isEmpty()&&!h.isEmpty()&&MessageDigest.isEqual(hash(pin,unhex(s)),unhex(h));}catch(Exception e){return false;}}
 public static int failed(Context c){return p(c).getInt("failed",0);} public static int fail(Context c){int n=failed(c)+1;p(c).edit().putInt("failed",n).apply();return n;} public static void resetFailures(Context c){p(c).edit().putInt("failed",0).apply();}
 public static void event(Context c,String s){p(c).edit().putString("event",s).putLong("event_time",System.currentTimeMillis()).apply();} public static String lastEvent(Context c){return p(c).getString("event","No event recorded");} public static long eventTime(Context c){return p(c).getLong("event_time",0);} public static void recordServiceStart(Context c){p(c).edit().putLong("service_start",System.currentTimeMillis()).apply();} public static long serviceStartTime(Context c){return p(c).getLong("service_start",0);} public static void boot(Context c,String a){p(c).edit().putInt("boots",p(c).getInt("boots",0)+1).putString("event","Boot receiver: "+a).putLong("event_time",System.currentTimeMillis()).apply();} public static int boots(Context c){return p(c).getInt("boots",0);}
 private static byte[] hash(String v,byte[] s)throws Exception{MessageDigest d=MessageDigest.getInstance("SHA-256");d.update(s);return d.digest(v.getBytes("UTF-8"));} private static String hex(byte[] b){StringBuilder s=new StringBuilder();for(byte x:b)s.append(String.format("%02x",x&255));return s.toString();} private static byte[] unhex(String s){byte[] b=new byte[s.length()/2];for(int i=0;i<b.length;i++)b[i]=(byte)Integer.parseInt(s.substring(2*i,2*i+2),16);return b;}
}
